export function validateCarouselDeck(value: unknown): CarouselDeckValidation {
  const issues: string[] = [];
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ok: false, issues: ["deck must be an object"] };
  }

  const deck = value as Record<string, unknown>;
  if (deck.aspect !== undefined && !isCarouselAspect(deck.aspect)) {
    issues.push("deck.aspect is invalid");
  }
  if (!Array.isArray(deck.slides) || deck.slides.length === 0) {
    issues.push("deck.slides must contain at least one slide");
    return { ok: false, issues };
  }
  if (deck.slides.length > CAROUSEL_DECK_LIMITS.slides) {
    issues.push(
      `deck.slides must contain at most ${CAROUSEL_DECK_LIMITS.slides} slides`
    );
  }
  validateText(
    deck.handle,
    "deck.handle",
    CAROUSEL_DECK_LIMITS.handle,
    issues,
    { optional: true }
  );
  if (
    deck.showPageNumber !== undefined &&
    typeof deck.showPageNumber !== "boolean"
  ) {
    issues.push("deck.showPageNumber must be a boolean");
  }
  if (
    deck.visualStyle !== undefined &&
    deck.visualStyle !== "editorial" &&
    deck.visualStyle !== "native-photo"
  ) {
    issues.push("deck.visualStyle is invalid");
  }

  const visualRequestIds = new Set<string>();
  deck.slides.forEach((value, index) => {
    const path = `deck.slides[${index}]`;
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      issues.push(`${path} must be an object`);
      return;
    }
    const slide = value as Record<string, unknown>;
    switch (slide.kind) {
      case "cover":
        validateText(
          slide.title,
          `${path}.title`,
          CAROUSEL_DECK_LIMITS.cover.title,
          issues
        );
        validateText(
          slide.accent,
          `${path}.accent`,
          CAROUSEL_DECK_LIMITS.cover.accent,
          issues,
          { optional: true }
        );
        validateText(
          slide.subtitle,
          `${path}.subtitle`,
          CAROUSEL_DECK_LIMITS.cover.subtitle,
          issues,
          { optional: true }
        );
        break;
      case "statement":
        validateText(
          slide.statement,
          `${path}.statement`,
          CAROUSEL_DECK_LIMITS.statement.statement,
          issues
        );
        validateText(
          slide.accent,
          `${path}.accent`,
          CAROUSEL_DECK_LIMITS.statement.accent,
          issues,
          { optional: true }
        );
        validateText(
          slide.footnote,
          `${path}.footnote`,
          CAROUSEL_DECK_LIMITS.statement.footnote,
          issues,
          { optional: true }
        );
        break;
      case "list":
        validateText(
          slide.title,
          `${path}.title`,
          CAROUSEL_DECK_LIMITS.list.title,
          issues
        );
        validateText(
          slide.accent,
          `${path}.accent`,
          CAROUSEL_DECK_LIMITS.list.accent,
          issues,
          { optional: true }
        );
        if (
          !Array.isArray(slide.items) ||
          slide.items.length === 0 ||
          slide.items.some((item) => !isNonEmptyString(item))
        ) {
          issues.push(`${path}.items must contain non-empty strings`);
        } else {
          if (slide.items.length > CAROUSEL_DECK_LIMITS.list.items) {
            issues.push(
              `${path}.items must contain at most ${CAROUSEL_DECK_LIMITS.list.items} items`
            );
          }
          slide.items.forEach((item, itemIndex) =>
            validateText(
              item,
              `${path}.items[${itemIndex}]`,
              CAROUSEL_DECK_LIMITS.list.item,
              issues
            )
          );
        }
        break;
      case "takeaway":
        validateText(
          slide.title,
          `${path}.title`,
          CAROUSEL_DECK_LIMITS.takeaway.title,
          issues
        );
        validateText(
          slide.accent,
          `${path}.accent`,
          CAROUSEL_DECK_LIMITS.takeaway.accent,
          issues,
          { optional: true }
        );
        validateText(
          slide.cta,
          `${path}.cta`,
          CAROUSEL_DECK_LIMITS.takeaway.cta,
          issues,
          { optional: true }
        );
        break;
      default:
        issues.push(`${path}.kind is invalid`);
    }
    validateOptionalImage(slide.image, `${path}.image`, issues);
    validateOptionalVisualRequest(
      slide.visualRequest,
      `${path}.visualRequest`,
      issues
    );
    if (
      slide.visualRequest &&
      typeof slide.visualRequest === "object" &&
      !Array.isArray(slide.visualRequest)
    ) {
      const id = (slide.visualRequest as Record<string, unknown>).id;
      if (isNonEmptyString(id)) {
        if (visualRequestIds.has(id)) {
          issues.push(
            `${path}.visualRequest.id must be unique within the deck`
          );
        }
        visualRequestIds.add(id);
      }
    }
  });

  return issues.length === 0
    ? { ok: true, slideCount: deck.slides.length }
    : { ok: false, issues };
}
